def _escape(expression, quote=True, escaper=None):
        retVal = expression

        if quote:
            for item in re.findall(r"'[^']*'+", expression, re.S):
                retVal = retVal.replace(item, escaper(item[1:-1]))
        else:
            retVal = escaper(expression)

        return retVal

